    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    sane_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) > 500:
                prev = opp.get('previous_trace', {}) or {}
                pb = prev.get('bid')
                if pb is not None and pb >= 100:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {}) or {}
            pb = prev.get('bid')
            if pb is not None:
                prev_bids.append(pb)
                if pb <= 95:
                    sane_bids.append(pb)

    if budget <= 0:
        return 0.0

    slots = int(supply / WATER_REQ)
    if slots < 1:
        slots = 1

    if not alive:
        return float(min(budget, 18.0))

    high_prev = max(prev_bids) if prev_bids else 0.0
    sane_high = max(sane_bids) if sane_bids else 0.0

    urgent = hp <= 2 or no_water >= 1
    very_urgent = hp <= 1 or no_water >= 2

    if very_urgent:
        bid = 112.0 if rich_aggressive == 0 else 128.0
        return float(min(budget, bid))

    if urgent:
        base = max(78.0, sane_high + 4.0)
        if rich_aggressive > 0:
            base = max(base, 96.0)
        if slots >= 2:
            base -= 6.0
        return float(min(budget, base))

    if slots >= 2:
        if rich_aggressive > 0:
            bid = 24.0 if hp >= 4 else 38.0
        else:
            bid = max(26.0, min(52.0, sane_high + 2.0 if sane_high > 0 else 32.0))
        if desperate_count >= 2:
            bid += 6.0
        return float(min(budget, bid))

    bid = max(34.0, sane_high + 3.0 if sane_high > 0 else 40.0)
    if rich_aggressive > 0:
        bid = 22.0 if hp >= 5 else 44.0
    if desperate_count >= 2:
        bid += 8.0
    if day >= 8 and hp >= 4:
        bid -= 6.0
    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how tight the water is: more scarcity -> bid more.
    # With supply in [15,25], total units relative to our requirement.
    water_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0
    scarcity = 1.0
    if water_units >= 2.5:
        scarcity = 0.75
    elif water_units >= 2.0:
        scarcity = 0.95
    else:
        scarcity = 1.15

    # Base bid depends on our urgency.
    if hp <= 2 or no_water_days >= 2:
        urgency = 1.25
    elif hp <= 4 or no_water_days >= 1:
        urgency = 1.05
    else:
        urgency = 0.9

    # If others were already bidding very high yesterday, we must match closer.
    # From trace: Cindy/Alex avg around ~105-114 with max ~135; use that scale.
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        target = DAILY_SALARY * 0.95 * scarcity * urgency
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        target = (highest_prev_bid * 0.85 + DAILY_SALARY * 0.25) * scarcity * urgency
    else:
        target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.6 + 10.0) * scarcity * urgency

    # Keep within budget and a reasonable cap (avoid overpaying early).
    cap = min(budget, DAILY_SALARY * 1.1)
    bid = max(0.0, min(cap, target))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_opponent_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0
    max_opponent_bid = max(yesterday_bids) if yesterday_bids else 0

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75
    elif my_hp > 7 and my_budget > DAILY_SALARY * 3:
        base_bid = DAILY_SALARY * 0.4

    estimated_water_per_agent = current_supply / (num_alive_opponents + 1)

    if estimated_water_per_agent < WATER_REQ:
        base_bid = max(base_bid, max_opponent_bid + 5, DAILY_SALARY * 0.8)
    elif estimated_water_per_agent >= WATER_REQ * 1.5:
        base_bid = min(base_bid, DAILY_SALARY * 0.3, avg_opponent_bid * 0.9 if avg_opponent_bid else base_bid)
    else:
        base_bid = max(base_bid, avg_opponent_bid + 1)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.95, max_opponent_bid + 10)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.7)
    elif current_day <= 2:
        if my_hp > 5:
            base_bid = min(base_bid, DAILY_SALARY * 0.6)

    final_bid = max(1.0, base_bid)

    final_bid = min(final_bid, my_budget)

    if my_budget < DAILY_SALARY and my_hp > 3:
        final_bid = min(final_bid, my_budget * 0.8)

    if my_no_water_days > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.75)

    return final_bid

